<?php require_once __DIR__.'/includes/bootstrap.php';$p=trim($_GET['purok']??'');$data=rows($pdo,'SELECT purok,COUNT(DISTINCT id) households,0 residents FROM families WHERE (:p="" OR purok=:p) GROUP BY purok ORDER BY purok',['p'=>$p]);?><!doctype html><html><head><meta charset="utf-8"><title>Census Summary</title><style>body{font:14px Arial;padding:30px}table{width:100%;border-collapse:collapse}td,th{border:1px solid #999;padding:8px;text-align:left}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Print / Save as PDF</button><h1>Barangay San Isidro Census Summary</h1><p>Generated <?=date('F j, Y')?></p><table><tr><th>Purok</th><th>Households</th><th>Residents</th></tr><?php foreach($data as $r):?><tr><td><?=h($r['purok'])?></td><td><?= (int)$r['households']?></td><td><?= (int)$r['residents']?></td></tr><?php endforeach;?></table></body></html>
